import { setupWorker } from 'msw/browser';
import { handlers } from '../test/handlers';

/**
 * Starts the MSW service worker with the same typed handlers the tests use.
 * Loaded with a dynamic import from main.tsx only when /config.json says `useMocks: true`,
 * so it does not weigh on the main bundle.
 * Needs public/mockServiceWorker.js (generated by `npx msw init public/ --save=false`, committed).
 */
export async function startMockWorker() {
  const worker = setupWorker(...handlers);
  await worker.start({ quiet: true });
}
